public with sharing class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;
    // 50,000 Ids / 200 per job = 250 chained jobs; allow headroom.
    // Raises the default stack depth limit (5 in Developer Edition / scratch orgs),
    // so the full chain runs, including within a test.
    private static final Integer MAX_STACK_DEPTH = 300;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds), buildOptions());
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Integer batchEnd = Math.min(BATCH_SIZE, accountIds.size());
        Set<Id> batchIds = new Set<Id>();
        for (Integer i = 0; i < batchEnd; i++) {
            batchIds.add(accountIds[i]);
        }

        List<Id> remaining = new List<Id>();
        for (Integer i = batchEnd; i < accountIds.size(); i++) {
            remaining.add(accountIds[i]);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account a : [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :batchIds]) {
            a.Rating = rate(a.AnnualRevenue);
            toUpdate.add(a);
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }

        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining), buildOptions());
        }
    }

    @TestVisible
    private static String rate(Decimal revenue) {
        if (revenue != null && revenue >= 1000000) {
            return 'Hot';
        }
        if (revenue != null && revenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    private static AsyncOptions buildOptions() {
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = MAX_STACK_DEPTH;
        return options;
    }
}
