public with sharing class LogPurgeJob implements Schedulable {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_EXPRESSION = '0 0 2 * * ?';
    public static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        Datetime now = Datetime.now();
        Datetime generalCutoff = now.addDays(-30);
        Datetime errorCutoff = now.addDays(-180);
        Database.executeBatch(new LogPurgeBatch(generalCutoff, errorCutoff), BATCH_SIZE);
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXPRESSION, new LogPurgeJob());
    }

    public with sharing class LogPurgeBatch implements Database.Batchable<SObject> {
        private final Datetime generalCutoff;
        private final Datetime errorCutoff;

        public LogPurgeBatch(Datetime generalCutoff, Datetime errorCutoff) {
            this.generalCutoff = generalCutoff;
            this.errorCutoff = errorCutoff;
        }

        public Database.QueryLocator start(Database.BatchableContext bc) {
            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :errorCutoff)
                   OR (CreatedDate < :generalCutoff
                       AND (Level__c = null OR Level__c != 'ERROR'))
                WITH USER_MODE
            ]);
        }

        public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
            Database.delete(scope, false, AccessLevel.USER_MODE);
        }

        public void finish(Database.BatchableContext bc) {
        }
    }
}
