public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per opportunity using a single
     * bulk EventBus.publish call (avoids the per-transaction limit on publish
     * calls when up to 200 records are passed in).
     *
     * The returned list is in the same order as the input list. Null entries
     * in the input are skipped (no event can be built for them).
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            if (opp == null) {
                continue;
            }
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id == null ? null : String.valueOf(opp.Id),
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            ));
        }

        if (events.isEmpty()) {
            return results;
        }

        // Single bulk call; results are returned in the same order as events.
        results.addAll(EventBus.publish(events));
        return results;
    }
}
