import { LightningElement, api } from 'lwc';
import FAVORITE_ADD from '@salesforce/label/c.Favorite_Add';
import FAVORITE_REMOVE from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }
    set favorite(value) {
        // Parent-driven changes always override the local (optimistic) state
        this._favorite = value === true;
    }

    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    get actionLabel() {
        return this._favorite ? FAVORITE_REMOVE : FAVORITE_ADD;
    }

    get buttonClass() {
        return this._favorite ? 'favorite-button is-favorite' : 'favorite-button';
    }

    get fillValue() {
        return this._favorite ? 'currentColor' : 'none';
    }

    handleClick() {
        // Optimistic UI: flip the private state immediately
        this._favorite = !this._favorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this._favorite }
            })
        );
    }
}
