import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeValue;

    @api
    get options() {
        return this._options;
    }
    set options(v) {
        this._options = Array.isArray(v) ? v : [];
        if (!this._hasOption(this._activeValue)) {
            this._activeValue = this._hasOption(this._value) ? this._value : undefined;
        }
    }

    @api
    get value() {
        return this._value;
    }
    set value(v) {
        this._value = v;
        this._activeValue = v;
    }

    _hasOption(val) {
        return (
            val !== undefined &&
            val !== null &&
            val !== '' &&
            this._options.some((o) => o.value === val)
        );
    }

    get _activeIndex() {
        if (!this._options.length) return -1;
        let i = this._hasOption(this._activeValue)
            ? this._options.findIndex((o) => o.value === this._activeValue)
            : -1;
        if (i < 0 && this._hasOption(this._value)) {
            i = this._options.findIndex((o) => o.value === this._value);
        }
        return i < 0 ? 0 : i;
    }

    get items() {
        const active = this._activeIndex;
        return this._options.map((o, i) => ({
            key: String(i) + '-' + String(o.value),
            value: o.value,
            label: o.label,
            index: i,
            selected: this._hasOption(this._value) && o.value === this._value ? 'true' : 'false',
            active: i === active,
            cssClass: 'slds-listbox__item' + (i === active ? ' active' : '')
        }));
    }

    renderedCallback() {
        const list = this.template.querySelector('ul');
        if (!list) return;
        const lis = this.template.querySelectorAll('li');
        lis.forEach((li, i) => {
            li.id = 'status-option-' + i;
        });
        const idx = this._activeIndex;
        if (idx >= 0 && lis[idx]) {
            list.setAttribute('aria-activedescendant', lis[idx].id);
        } else {
            list.removeAttribute('aria-activedescendant');
        }
    }

    handleKeydown(event) {
        const n = this._options.length;
        const key = event.key;
        const handled = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!handled.includes(key)) return;
        event.preventDefault();
        if (!n) return;
        const cur = this._activeIndex;
        let next = cur;
        if (key === 'ArrowDown') next = Math.min(cur + 1, n - 1);
        else if (key === 'ArrowUp') next = Math.max(cur - 1, 0);
        else if (key === 'Home') next = 0;
        else if (key === 'End') next = n - 1;
        else {
            this._select(this._options[cur].value);
            return;
        }
        this._activeValue = this._options[next].value;
    }

    handleClick(event) {
        const idx = Number(event.currentTarget.dataset.index);
        const opt = this._options[idx];
        if (!opt) return;
        this._select(opt.value);
    }

    _select(val) {
        this._activeValue = val;
        if (val === this._value) return;
        this._value = val;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: val } }));
    }
}
