public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // Validate everything before any DML
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest r = requests[i];
            if (r == null) {
                throw new RecurringGiftException('Request ' + i + ' is null.');
            }
            if (r.contactId == null) {
                throw new RecurringGiftException('Request ' + i + ': contact is required.');
            }
            if (r.amount == null || r.amount <= 0) {
                throw new RecurringGiftException('Request ' + i + ': amount must be greater than zero.');
            }
            if (r.dayOfMonth == null || r.dayOfMonth < 1 || r.dayOfMonth > 31) {
                throw new RecurringGiftException('Request ' + i + ': day of month must be between 1 and 31.');
            }
            if (r.startDate == null) {
                throw new RecurringGiftException('Request ' + i + ': start date is required.');
            }
            if (r.installments != null && r.installments < 0) {
                throw new RecurringGiftException('Request ' + i + ': installments cannot be negative.');
            }
        }

        List<npe03__Recurring_Donation__c> rds = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest r : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            rd.npe03__Contact__c = r.contactId;
            rd.npe03__Amount__c = r.amount;
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 1;
            rd.npsp__StartDate__c = r.startDate;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = r.paymentMethod;

            // 31 means last day of month; the ERD picklist value is 'Last_Day'
            // (npsp__Always_Use_Last_Day_Of_Month__c is derived from it)
            if (r.dayOfMonth == 31) {
                rd.npsp__Day_of_Month__c = 'Last_Day';
            } else {
                rd.npsp__Day_of_Month__c = String.valueOf(r.dayOfMonth);
            }

            if (r.installments == null || r.installments == 0) {
                rd.npsp__RecurringType__c = 'Open';
            } else {
                rd.npsp__RecurringType__c = 'Fixed';
                rd.npe03__Installments__c = r.installments;
            }
            rds.add(rd);
        }

        insert rds;

        for (npe03__Recurring_Donation__c rd : rds) {
            result.add(rd.Id);
        }
        return result;
    }
}
