public inherited sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    public void execute(FinalizerHandler.Context context) {
        // Called at the end of every DML operation for any sObject: do nothing if nothing was collected.
        Set<Id> ids = TA_Opportunity_CollectForErpSync.drain();
        if (ids.isEmpty()) {
            return;
        }
        // Enqueuing a job is not DML.
        System.enqueueJob(new OpportunityErpSyncJob(ids));
    }
}
